const files = $json.files || [];
const CHAR_LIMIT_PER_CHUNK = 12000; // ~3000 tokens, safely under 6000 TPM with prompt overhead

let chunks = [];
let currentChunk = [];
let currentSize = 0;

for (const f of files) {
  const size = (f.patch || '').length;
  if (currentSize + size > CHAR_LIMIT_PER_CHUNK && currentChunk.length > 0) {
    chunks.push(currentChunk);
    currentChunk = [];
    currentSize = 0;
  }
  currentChunk.push(f);
  currentSize += size;
}
if (currentChunk.length > 0) chunks.push(currentChunk);

return {
  json: {
    ...$json,
    needs_chunking: chunks.length > 1,
    chunks: chunks
  }
};

const raw = $json.choices[0].message.content;
const finishReason = $json.choices[0].finish_reason;

if (finishReason === 'length') {
  throw new Error(`Groq response was truncated (hit max_tokens) before completing valid JSON. Raw content was: ${raw.substring(0, 300)}`);
}

let cleaned = raw.replace(/```json|```/g, '').trim();
const start = cleaned.indexOf('{');
const end = cleaned.lastIndexOf('}');
if (start !== -1 && end !== -1 && end > start) {
  cleaned = cleaned.substring(start, end + 1);
} else {
  throw new Error(`Invalid JSON structure. Could not find valid '{' and '}' positions. Raw content was: ${raw.substring(0, 500)}`);
}

let parsed;
try {
  console.log('Attempting to parse JSON:', cleaned);
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(`Failed to parse JSON: ${error.message}. Raw content was: ${raw.substring(0, 500)}`);
}

// Chunked path already built file_changes with blob_url via "Build Combined Prompt"
// Single-call path returns file_changes directly in this response, without blob_url yet
let fileChanges;
let cameFromChunkedPath = false;
try {
  fileChanges = $('Build Combined Prompt').item.json.file_changes;
  cameFromChunkedPath = true;
} catch (e) {
  fileChanges = parsed.file_changes || [];
}

const commitSha = $('GitHub - Fetch Commit Diff').item.json.sha;

// if single-call path, compute blob_url the same way the chunked path does
if (!cameFromChunkedPath) {
  const crypto = require('crypto');
  fileChanges = fileChanges.map(f => ({
    ...f,
    blob_url: `https://github.com/voipmonitor/sniffer/commit/${commitSha}#diff-${crypto.createHash('sha256').update((f.filename || '').trim()).digest('hex')}`
  }));
}

return {
  json: {
    commit_sha: commitSha,
    commit_date: $('GitHub - Fetch Commit Diff').item.json.commit.author.date,
    author: $('GitHub - Fetch Commit Diff').item.json.commit.author.name,
    commit_url: $('GitHub - Fetch Commit Diff').item.json.html_url,
    summary: parsed.summary,
    priority: parsed.priority,
    review_recommendation: parsed.review_recommendation,
    reasoning: parsed.reasoning,
    file_changes: fileChanges
  }
};

const rows = $json.data;
const majorCount = rows.filter(r => r.priority === 'Major').length;
const minorCount = rows.filter(r => r.priority === 'Minor').length;
const tableRows = rows.map(r => {
  let fileChangesHtml = '';
  let filePurposesHtml = '';
  try {
    const files = JSON.parse(r.file_changes || '[]');
    const purposes = JSON.parse(r.file_purposes || '{}');

    if (files.length > 0) {
      fileChangesHtml = '<br><br><b>Per-file changes:</b><br>' + files.map(f =>
        `<div style="margin-top:8px;"><a href="${f.blob_url || '#'}" target="_blank" style="font-family:monospace;font-weight:bold;">${f.filename}</a>: ${f.changes}</div>`
      ).join('');
    }

    const purposeEntries = Object.entries(purposes);
    if (purposeEntries.length > 0) {
      filePurposesHtml = '<br><br><b>File purposes:</b><br>' + purposeEntries.map(([filename, desc]) =>
        `<div style="margin-top:6px;"><span style="font-family:monospace;font-weight:bold;">${filename}</span>: ${desc}</div>`
      ).join('');
    }
  } catch (e) { /* skip if malformed */ }
  return `
    <tr>
      <td style="padding:8px;border:1px solid #ddd;vertical-align:top;"><a href="${r.commit_url}" target="_blank">${r.commit_sha.substring(0,7)}</a></td>
      <td style="padding:8px;border:1px solid #ddd;vertical-align:top;">${r.commit_date}</td>
      <td style="padding:8px;border:1px solid #ddd;vertical-align:top;">${r.author}</td>
      <td style="padding:8px;border:1px solid #ddd;vertical-align:top;"><b>Summary:</b> ${r.summary}${fileChangesHtml}</td>
      <td style="padding:8px;border:1px solid #ddd;vertical-align:top;"><b>${r.priority}</b></td>
      <td style="padding:8px;border:1px solid #ddd;vertical-align:top;">${r.review_recommendation}</td>
      <td style="padding:8px;border:1px solid #ddd;vertical-align:top;">${r.reasoning}${filePurposesHtml}</td>
    </tr>
  `;
}).join('');
const html = `
  <h2>VoIPmonitor Sniffer - Weekly Change Digest</h2>
  <p>${rows.length} commits processed. <b>${majorCount} Major</b>, ${minorCount} Minor.</p>
  <table style="border-collapse:collapse;width:100%;font-family:sans-serif;font-size:13px;">
    <thead style="background:#f4f4f4;">
      <tr>
        <th style="padding:8px;border:1px solid #ddd;">SHA</th>
        <th style="padding:8px;border:1px solid #ddd;">Date</th>
        <th style="padding:8px;border:1px solid #ddd;">Author</th>
        <th style="padding:8px;border:1px solid #ddd;">Summary & File Changes</th>
        <th style="padding:8px;border:1px solid #ddd;">Priority</th>
        <th style="padding:8px;border:1px solid #ddd;">Review?</th>
        <th style="padding:8px;border:1px solid #ddd;">Reasoning</th>
      </tr>
    </thead>
    <tbody>${tableRows}</tbody>
  </table>
`;
return { json: { html } };

