return parsed.map(p => ({ json: p }));

const filenames = $('Build Combined Prompt').item.json.file_changes.map(f => f.filename);
// Build a proper Postgres array literal string: {"file1.cpp","file2.h"}
const pgArrayLiteral = '{' + filenames.map(f => `"${f.replace(/"/g, '\\"')}"`).join(',') + '}';

return {
  json: {
    filenames: filenames,
    pg_array_literal: pgArrayLiteral
  }
};

// gather known_purposes from earlier + any newly generated ones from this run
const mergedData = $('Merge Known + Find Unknown').first().json;
const knownPurposes = mergedData.known_purposes;
const newlyGenerated = $input.all().map(item => item.json); // from the true branch, if it ran
const allPurposes = { ...knownPurposes };
for (const p of newlyGenerated) {
  if (p.filename && p.description) allPurposes[p.filename] = p.description;
}

return {
  json: {
    ...mergedData,              // preserves commit_sha, summary, priority, commit_url, etc.
    file_changes: mergedData.file_changes,
    file_purposes: allPurposes
  }
};

